package com.genai.backend.service;

import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.stereotype.Service;

import java.io.IOException;
import java.io.UncheckedIOException;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.Paths;
import java.util.UUID;

/**
 * Persists binary media generated by AI models (audio, and image fallbacks) to local disk and
 * hands back a public relative URL served by {@link com.genai.backend.config.MediaWebConfig}.
 */
@Service
public class MediaStorageService {

    private static final Logger log = LoggerFactory.getLogger(MediaStorageService.class);

    private final Path storageRoot;

    public MediaStorageService(@Value("${app.media.storage-dir}") String storageDir) {
        this.storageRoot = Paths.get(storageDir).toAbsolutePath().normalize();
        try {
            Files.createDirectories(storageRoot);
        } catch (IOException e) {
            throw new UncheckedIOException("Unable to initialize media storage directory: " + storageRoot, e);
        }
    }

    /**
     * Stores the given bytes under a category subdirectory using a random filename, guarding
     * against path traversal via the caller-supplied subdirectory.
     */
    public String store(byte[] data, String subDir, String extension) {
        Path targetDir = storageRoot.resolve(subDir).normalize();
        if (!targetDir.startsWith(storageRoot)) {
            throw new IllegalArgumentException("Invalid storage subdirectory: " + subDir);
        }
        try {
            Files.createDirectories(targetDir);
            String filename = UUID.randomUUID() + "." + extension;
            Path target = targetDir.resolve(filename);
            Files.write(target, data);
            log.debug("Stored generated media at {}", target);
            return "/media/" + subDir + "/" + filename;
        } catch (IOException e) {
            throw new UncheckedIOException("Failed to persist generated media", e);
        }
    }
}
